// src/lib/mcp/tools/list-retailers.ts
var list_retailers_default = defineTool({
  name: "list_retailers",
  title: "List retailers",
  description: "List retailers (dealers) in the Pune trading area with their segment, engagement score, openness and last visit outcome. Optionally filter by segment or area.",
  inputSchema: {
    segment: z.enum(["new", "loyal", "inactive", "declining"]).optional().describe("Filter by retailer segment."),
    area: z.string().optional().describe("Filter by market area, e.g. 'Hinjewadi'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ segment, area }) => {
    const rows = dealers.filter(
      (d) => (!segment || d.type === segment) && (!area || d.area.toLowerCase().includes(area.toLowerCase()))
    );
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { count: rows.length, retailers: rows }
    };
  }
});

// src/lib/mcp/tools/get-retailer.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var get_retailer_default = defineTool2({
  name: "get_retailer",
  title: "Get retailer snapshot",
  description: "Get the full snapshot for one retailer by id, dealer code, or (partial) name.",
  inputSchema: {
    query: z2.string().min(1).describe("Retailer id, dealer code, or part of the name.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query }) => {
    const q = query.trim().toLowerCase();
    const dealer = dealers.find((d) => d.id === q || d.dealerCode.toLowerCase() === q) ?? dealers.find((d) => d.name.toLowerCase().includes(q));
    if (!dealer) throw new ToolError(`No retailer matched "${query}".`);
    return {
      content: [{ type: "text", text: JSON.stringify(dealer, null, 2) }],
      structuredContent: { retailer: dealer }
    };
  }
});

