// src/lib/mcp/tools/list-market-insights.ts
var list_market_insights_default = defineTool3({
  name: "list_market_insights",
  title: "List market insights",
  description: "List field-reported market insights (competition, product quality, schemes, customer, demand) with frequency and actionability.",
  inputSchema: {
    category: z3.enum(["Competition", "Product Quality", "Schemes", "Customer", "Demand"]).optional().describe("Filter by insight category."),
    state: z3.string().optional().describe("Filter to insights reported in a given state.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, state }) => {
    const rows = nationalInsights.filter(
      (i) => (!category || i.category === category) && (!state || i.states.some((s) => s.toLowerCase() === state.toLowerCase()))
    );
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { count: rows.length, insights: rows }
    };
  }
});

// src/lib/mcp/tools/list-objections.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z4 } from "npm:zod@^3.25.76";
var list_objections_default = defineTool4({
  name: "list_objections",
  title: "List retailer objections",
  description: "Retailer objection mix \u2014 overall share, per-state counts and per-area breakdown. Optionally scope to one state.",
  inputSchema: {
    state: z4.string().optional().describe("Restrict counts to a single state, e.g. 'Maharashtra'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ state }) => {
    const key = state ? Object.keys(stateObjectionMatrix).find((s) => s.toLowerCase() === state.toLowerCase()) : void 0;
    const payload = {
      objectionTypes: [...objectionTypes],
      overallSharePercent: objectionBreakdown,
      stateCounts: key ? { [key]: stateObjectionMatrix[key] } : stateObjectionMatrix,
      areaBreakdown: areaObjections
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

// src/lib/mcp/tools/get-engagement-playbook.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z5 } from "npm:zod@^3.25.76";
var get_engagement_playbook_default = defineTool5({
  name: "get_engagement_playbook",
  title: "Get engagement playbook",
  description: "Field engagement playbook: conversation themes, discussion points, common retailer objections and the recommended responses / best practices.",
  inputSchema: {
    theme: z5.string().optional().describe("Filter themes by id or part of the title.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ theme }) => {
    const q = theme?.trim().toLowerCase();
    const themes = q ? engagementThemes.filter((t) => t.id === q || t.title.toLowerCase().includes(q)) : engagementThemes;
    const payload = { themes, discussionPoints };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

// src/lib/mcp/tools/get-engagement-overview.ts
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z6 } from "npm:zod@^3.25.76";
var get_engagement_overview_default = defineTool6({
  name: "get_engagement_overview",
  title: "Get engagement overview",
  description: "National retailer-engagement overview: headline KPIs, month-on-month trend, per-state coverage and the top-performing marketing executives.",
  inputSchema: {
    state: z6.string().optional().describe("Restrict the state breakdown to one state.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ state }) => {
    const stateRows = state ? states.filter((s) => s.state.toLowerCase() === state.toLowerCase()) : states;
    const payload = {
      kpis: {
        totalRetailers: NATIONAL_TOTAL_RETAILERS,
        retailersEngaged: NATIONAL_RETAILERS_ENGAGED,
        totalMes: NATIONAL_TOTAL_MES,
        activeMes: NATIONAL_ACTIVE_MES,
        totalAsms: NATIONAL_TOTAL_ASMS,
        avgEngagementsPerRetailer: NATIONAL_AVG_ENGAGEMENT_PER_RETAILER,
        benchmarkEngagementsPerRetailer: ENGAGEMENT_BENCHMARK_PER_RETAILER
      },
      monthOnMonthTrend: momTrend,
      states: stateRows,
      topMarketingExecutives: topMEs
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

